def run_weekly_overdue_invoice_reminders() -> dict[str, object]:
    """Return delivered only after complete preflight, one confirmed reminder per invoice, and one confirmed digest; otherwise notify the owner and return held. Implements the policy in guidance “Fail-closed weekly invoice delivery policy”."""
    import logging

    log = logging.getLogger(__name__)
    log.info("PHASE weekly-invoice-run starting read-only preflight")
    preflight = read_weekly_invoice_preflight()
    if type(preflight) is not dict or preflight.get("status") not in {"ready", "hold"}:
        log.error("SOFT_FAIL preflight returned an invalid internal result contract")
        return post_invoice_owner_hold("internal preflight result contract anomaly; no reminders or digest were attempted")
    if preflight["status"] == "hold":
        message = preflight.get("message")
        if type(message) is not str or not message:
            message = "preflight stopped without a usable diagnostic; no reminders or digest were attempted"
        log.warning("SKIP delivery preflight_hold")
        return post_invoice_owner_hold(message)

    week = preflight.get("week")
    invoices = preflight.get("invoices")
    invoice_count = preflight.get("invoice_count")
    total_amount_cents = preflight.get("total_amount_cents")
    if (
        type(week) is not int
        or type(invoices) is not list
        or type(invoice_count) is not int
        or type(total_amount_cents) is not int
        or invoice_count != len(invoices)
        or preflight.get("flagged_invoice_ids") != []
    ):
        log.error("SOFT_FAIL preflight ready result failed root validation")
        return post_invoice_owner_hold("internal validated-batch contract anomaly; no reminders or digest were attempted")

    accepted_ids: list[str] = []
    if invoice_count == 0:
        log.info("SKIP reminder-delivery valid invoice batch is empty")
    else:
        log.info("PHASE reminder-delivery sending count=%s", invoice_count)
        for record in invoices:
            if type(record) is not dict or type(record.get("id")) is not str or type(record.get("contact_email")) is not str:
                log.error("SOFT_FAIL reminder-delivery validated record contract changed before delivery")
                accepted_desc = ", ".join(repr(value) for value in accepted_ids) if accepted_ids else "none"
                return post_invoice_owner_hold(
                    f"week {week} validated invoice data became unusable before reminder delivery; stopped further delivery, skipped digest, and {len(accepted_ids)} reminder(s) were already accepted (ids: {accepted_desc})"
                )
            invoice_id = record["id"]
            try:
                post_invoice_reminder(record["contact_email"], invoice_id)
            except Exception as exc:
                log.warning("SOFT_FAIL reminder-delivery invoice_id=%r not confirmed: %s", invoice_id, exc)
                accepted_desc = ", ".join(repr(value) for value in accepted_ids) if accepted_ids else "none"
                return post_invoice_owner_hold(
                    f"week {week} reminder for invoice id {invoice_id!r} was not confirmed ({exc}); stopped further delivery, skipped digest, and {len(accepted_ids)} reminder(s) were already accepted (ids: {accepted_desc})"
                )
            accepted_ids.append(invoice_id)

    digest: dict[str, object] = {
        "week": week,
        "invoice_count": invoice_count,
        "total_amount_cents": total_amount_cents,
        "reminders_sent": len(accepted_ids),
        "flagged_invoice_ids": [],
    }
    if digest["reminders_sent"] != digest["invoice_count"]:
        log.error("SOFT_FAIL report-delivery reminder count invariant failed")
        accepted_desc = ", ".join(repr(value) for value in accepted_ids) if accepted_ids else "none"
        return post_invoice_owner_hold(
            f"week {week} reminder count invariant failed after {len(accepted_ids)} accepted reminder(s) (ids: {accepted_desc}); digest was not posted"
        )

    try:
        report_result = post_invoice_digest(digest)
    except Exception as exc:
        log.warning("SOFT_FAIL report-delivery digest not confirmed: %s", exc)
        accepted_desc = ", ".join(repr(value) for value in accepted_ids) if accepted_ids else "none"
        return post_invoice_owner_hold(
            f"week {week} report was not confirmed ({exc}); {len(accepted_ids)} reminder(s) may already have been delivered (ids: {accepted_desc}), and the report was not retried"
        )

    log.info("PHASE complete week=%s reminders=%s", week, len(accepted_ids))
    return {
        "status": "delivered",
        "report_http_status": report_result["http_status"],
        "digest": digest,
        "accepted_invoice_ids": accepted_ids,
    }

