def post_invoice_digest(digest: dict[str, object]) -> dict[str, object]:
    """Post exactly one contract-valid weekly digest and return only after confirmed HTTP 2xx. Implements the policy in guidance “Fail-closed weekly invoice delivery policy”."""
    import json
    import logging
    import urllib.error
    import urllib.request

    log = logging.getLogger(__name__)
    expected_keys = {"week", "invoice_count", "total_amount_cents", "reminders_sent", "flagged_invoice_ids"}
    if type(digest) is not dict or set(digest.keys()) != expected_keys:
        raise ValueError("digest must contain exactly the five required keys")
    for key in ("week", "invoice_count", "total_amount_cents", "reminders_sent"):
        if type(digest[key]) is not int:
            raise ValueError(f"digest field {key!r} must be a strict integer")
    if digest["week"] < 1 or digest["invoice_count"] < 0 or digest["reminders_sent"] < 0:
        raise ValueError("digest week/count fields are out of range")
    if digest["reminders_sent"] != digest["invoice_count"]:
        raise ValueError("reminders_sent must equal invoice_count")
    if type(digest["flagged_invoice_ids"]) is not list or digest["flagged_invoice_ids"] != []:
        raise ValueError("flagged_invoice_ids must be an empty list for delivery")

    body = json.dumps(digest, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    request = urllib.request.Request(
        "http://127.0.0.1:18282/report",
        data=body,
        headers={"Accept": "application/json", "Content-Type": "application/json"},
        method="POST",
    )
    log.info("PHASE report-delivery posting validated digest")
    try:
        with urllib.request.urlopen(request, timeout=5.0) as response:
            status = response.getcode()
            response.read()
    except urllib.error.HTTPError as exc:
        try:
            detail = exc.read(512).decode("utf-8", errors="replace")
        except Exception:
            detail = ""
        suffix = f" ({detail[:160]})" if detail else ""
        log.warning("SOFT_FAIL report-delivery HTTP=%s", exc.code)
        raise RuntimeError(f"POST /report returned HTTP {exc.code}{suffix}") from exc
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        log.warning("SOFT_FAIL report-delivery outcome uncertain")
        raise RuntimeError(f"POST /report transport outcome uncertain: {type(exc).__name__}: {exc}") from exc
    if not (200 <= status < 300):
        log.warning("SOFT_FAIL report-delivery HTTP=%s", status)
        raise RuntimeError(f"POST /report returned HTTP {status}")
    log.info("PHASE report-delivery accepted HTTP=%s", status)
    return {"accepted": True, "http_status": status}

