def post_invoice_owner_hold(message: str) -> dict[str, object]:
    """Post exactly one owner notification whose sole JSON field is `message` prefixed with `HOLD:`, and return only after confirmed HTTP 2xx. Implements the policy in guidance “Fail-closed weekly invoice delivery policy”."""
    import json
    import logging
    import urllib.error
    import urllib.request

    log = logging.getLogger(__name__)
    if type(message) is not str or not message.strip():
        raise ValueError("message must be a non-empty string without the HOLD prefix")
    if message.lstrip().startswith("HOLD:"):
        raise ValueError("message must not already contain the HOLD prefix")
    payload = {"message": "HOLD: " + message.strip()}
    body = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    request = urllib.request.Request(
        "http://127.0.0.1:18282/owner/notify",
        data=body,
        headers={"Accept": "application/json", "Content-Type": "application/json"},
        method="POST",
    )
    log.warning("PHASE owner-notify posting HOLD notification")
    try:
        with urllib.request.urlopen(request, timeout=5.0) as response:
            status = response.getcode()
            response.read()
    except urllib.error.HTTPError as exc:
        try:
            detail = exc.read(512).decode("utf-8", errors="replace")
        except Exception:
            detail = ""
        suffix = f" ({detail[:160]})" if detail else ""
        log.exception("SOFT_FAIL owner-notify returned HTTP %s%s", exc.code, suffix)
        raise RuntimeError(f"POST /owner/notify returned HTTP {exc.code}{suffix}") from exc
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        log.exception("SOFT_FAIL owner-notify transport outcome uncertain")
        raise RuntimeError(f"POST /owner/notify transport outcome uncertain: {type(exc).__name__}: {exc}") from exc
    if not (200 <= status < 300):
        log.error("SOFT_FAIL owner-notify returned HTTP %s", status)
        raise RuntimeError(f"POST /owner/notify returned HTTP {status}")
    log.info("PHASE owner-notify accepted HTTP %s", status)
    return {"status": "held", "owner_notified": True, "message": payload["message"], "http_status": status}

