def read_weekly_invoice_preflight() -> dict[str, object]:
    """Return a fully validated ready batch or a delivery-blocking HOLD reason after exactly the required read-only preflight. Implements the policy in guidance “Fail-closed weekly invoice delivery policy”."""
    import logging
    import urllib.error
    import urllib.request

    log = logging.getLogger(__name__)
    base_url = "http://127.0.0.1:18282"
    timeout_seconds = 5.0

    def get_text(path: str) -> str:
        request = urllib.request.Request(
            base_url + path,
            headers={"Accept": "application/json"},
            method="GET",
        )
        try:
            with urllib.request.urlopen(request, timeout=timeout_seconds) as response:
                status = response.getcode()
                raw = response.read()
        except urllib.error.HTTPError as exc:
            try:
                detail = exc.read(512).decode("utf-8", errors="replace")
            except Exception:
                detail = ""
            suffix = f" ({detail[:160]})" if detail else ""
            raise RuntimeError(f"GET {path} returned HTTP {exc.code}{suffix}") from exc
        except (urllib.error.URLError, TimeoutError, OSError) as exc:
            raise RuntimeError(f"GET {path} transport failure: {type(exc).__name__}: {exc}") from exc
        if not (200 <= status < 300):
            raise RuntimeError(f"GET {path} returned HTTP {status}")
        try:
            return raw.decode("utf-8", errors="strict")
        except UnicodeDecodeError as exc:
            raise RuntimeError(f"GET {path} returned non-UTF-8 response bytes") from exc

    log.info("PHASE preflight reading and validating last completed report")
    try:
        last_json_text = get_text("/reports/last")
        last_week = parse_last_invoice_report(last_json_text)
        week = last_week + 1
    except Exception as exc:
        reason = f"last-report preflight anomaly: {exc}; invoice week could not be determined, so no deliveries were attempted"
        log.warning("SOFT_FAIL preflight last_report: %s", reason)
        return {"status": "hold", "message": reason}

    log.info("PHASE preflight reading invoices week=%s", week)
    try:
        invoices_json_text = get_text(f"/invoices?week={week}")
    except Exception as exc:
        reason = f"week {week} invoice-batch preflight anomaly: {exc}; no deliveries were attempted"
        log.warning("SOFT_FAIL preflight invoice_read: %s", reason)
        return {"status": "hold", "message": reason}

    return validate_weekly_invoice_batch(week, invoices_json_text)

