def validate_weekly_invoice_batch(week: int, invoices_json_text: str) -> dict[str, object]:
    """Return a ready batch summary only when every invoice satisfies the complete strict contract, otherwise return a HOLD reason. Implements the policy in guidance “Fail-closed weekly invoice delivery policy”."""
    import json
    import logging

    log = logging.getLogger(__name__)
    if type(week) is not int or week < 1:
        reason = (
            f"invoice-batch preflight anomaly: week {week!r} was not a strict positive integer; "
            "no deliveries were attempted"
        )
        log.warning("SOFT_FAIL preflight invalid week: %s", reason)
        return {"status": "hold", "message": reason}

    def no_duplicate_keys(pairs: list[tuple[str, object]]) -> dict[str, object]:
        result: dict[str, object] = {}
        for key, value in pairs:
            if key in result:
                raise ValueError(f"duplicate JSON object key {key!r}")
            result[key] = value
        return result

    def reject_nonfinite(value: str) -> object:
        raise ValueError(f"non-standard JSON numeric constant {value!r}")

    try:
        document = json.loads(
            invoices_json_text,
            object_pairs_hook=no_duplicate_keys,
            parse_constant=reject_nonfinite,
        )
    except (json.JSONDecodeError, UnicodeError, ValueError) as exc:
        reason = f"week {week} invoice-batch preflight anomaly: malformed or ambiguous JSON ({exc}); no deliveries were attempted"
        log.warning("SOFT_FAIL preflight invoice JSON: %s", reason)
        return {"status": "hold", "message": reason}
    if type(document) is not list:
        reason = f"week {week} invoice-batch preflight anomaly: response JSON was not a list; no deliveries were attempted"
        log.warning("SOFT_FAIL preflight invoice shape: %s", reason)
        return {"status": "hold", "message": reason}

    log.info("PHASE preflight validating complete invoice batch count=%s", len(document))
    required = ("id", "vendor", "amount_cents", "currency", "days_overdue", "contact_email")
    anomalies: list[str] = []
    valid_invoices: list[dict[str, object]] = []
    id_positions: dict[str, int] = {}

    for position, record in enumerate(document):
        usable_id = record.get("id") if type(record) is dict and type(record.get("id")) is str else None
        label = (
            f"invoice id {usable_id!r} at list position {position}"
            if usable_id is not None
            else f"record at list position {position} (no usable id)"
        )
        errors: list[str] = []
        if type(record) is not dict:
            errors.append("element is not a JSON object")
        else:
            missing = [field for field in required if field not in record]
            if missing:
                errors.append("missing fields " + ", ".join(missing))
            if "id" in record and type(record["id"]) is not str:
                errors.append("id is not a string")
            if "vendor" in record and type(record["vendor"]) is not str:
                errors.append("vendor is not a string")
            if "amount_cents" in record and type(record["amount_cents"]) is not int:
                errors.append("amount_cents is not a strict integer")
            if "currency" in record and (type(record["currency"]) is not str or record["currency"] != "EUR"):
                errors.append("currency is not the string 'EUR'")
            if "days_overdue" in record and type(record["days_overdue"]) is not int:
                errors.append("days_overdue is not a strict integer")
            if "contact_email" in record and type(record["contact_email"]) is not str:
                errors.append("contact_email is not a string")
            if type(record.get("id")) is str:
                invoice_id = record["id"]
                prior = id_positions.get(invoice_id)
                if prior is not None:
                    errors.append(f"duplicate id also present at list position {prior}")
                else:
                    id_positions[invoice_id] = position
        if errors:
            anomalies.append(f"{label}: " + ", ".join(errors))
        else:
            valid_invoices.append(record)

    if anomalies:
        detail = "; ".join(anomalies)
        if len(detail) > 1200:
            detail = detail[:1176].rstrip() + "; additional detail omitted"
        reason = (
            f"week {week} preflight found {len(anomalies)} invalid or ambiguous record(s): "
            f"{detail}; no reminders or digest were posted"
        )
        log.warning("SOFT_FAIL preflight invalid_records=%s detail=%s", len(anomalies), detail)
        return {"status": "hold", "message": reason}

    total_amount_cents = sum(record["amount_cents"] for record in valid_invoices)
    invoice_count = len(id_positions)
    log.info(
        "PHASE preflight batch passed week=%s invoice_count=%s total_amount_cents=%s",
        week,
        invoice_count,
        total_amount_cents,
    )
    return {
        "status": "ready",
        "week": week,
        "invoices": valid_invoices,
        "invoice_count": invoice_count,
        "total_amount_cents": total_amount_cents,
        "flagged_invoice_ids": [],
    }

