def parse_last_invoice_report(last_json_text: str) -> int:
    """Return the strict non-negative `last_week` integer from the exact last-report JSON contract. Implements the policy in guidance “Fail-closed weekly invoice delivery policy”."""
    import json

    def no_duplicate_keys(pairs: list[tuple[str, object]]) -> dict[str, object]:
        result: dict[str, object] = {}
        for key, value in pairs:
            if key in result:
                raise ValueError(f"duplicate JSON object key {key!r}")
            result[key] = value
        return result

    def reject_nonfinite(value: str) -> object:
        raise ValueError(f"non-standard JSON numeric constant {value!r}")

    try:
        document = json.loads(
            last_json_text,
            object_pairs_hook=no_duplicate_keys,
            parse_constant=reject_nonfinite,
        )
    except (json.JSONDecodeError, UnicodeError, ValueError) as exc:
        raise ValueError(f"GET /reports/last returned malformed or ambiguous JSON: {exc}") from exc
    if type(document) is not dict or set(document.keys()) != {"last_week"}:
        raise ValueError("GET /reports/last JSON did not exactly match the object contract with only key 'last_week'")
    last_week = document["last_week"]
    if type(last_week) is not int or last_week < 0:
        raise ValueError("GET /reports/last field 'last_week' was not a strict non-negative integer")
    return last_week
